const p = msg.payload || {};
const integer = v => {
  if (typeof v === "number") return Number.isSafeInteger(v) ? v : null;
  if (typeof v !== "string" || v.trim().length > 4 || !/^-?\d+$/.test(v.trim())) return null;
  const n = Number(v.trim()); return Number.isSafeInteger(n) ? n : null;
};
const start = integer(p.start), duration = integer(p.duration);
let reasonCode = null;
if (start === null || start < 0 || start > 1439) reasonCode = "INVALID_START";
else if (duration === null || duration <= 0 || duration > 120) reasonCode = "INVALID_DURATION";
else if (start + duration > 1440) reasonCode = "DAY_END_EXCEEDED";
else if (start <= msg.now) reasonCode = "PAST_START";
else if (typeof p.blocked !== "boolean") reasonCode = "INVALID_BLOCKED";
msg.validationOK = reasonCode === null;
msg.request = { start, duration, blocked: p.blocked === true };
msg.result = { availability: false, valid: false, reasonCode };
return msg;

const s = msg.request.start, e = s + msg.request.duration;
const occupied = msg.bookings.some(b => s < b.end && e > b.start);
msg.result = { availability: !occupied, valid: true, reasonCode: occupied ? "OVERLAP" : "AVAILABLE" };
return msg;

const messages = {"AVAILABLE": "Available. The requested interval is free; no booking has been created.", "OVERLAP": "Unavailable. The interval overlaps the existing 10:00-11:00 booking.", "ROOM_BLOCKED": "Unavailable. Room B-204 is blocked.", "INVALID_START": "Enter a whole-number start from 0 to 1439 minutes.", "INVALID_DURATION": "Enter a whole-number duration greater than 0 and at most 120 minutes.", "PAST_START": "Start must be strictly after the fixed current time, 09:00 (540).", "DAY_END_EXCEEDED": "The interval must end by minute 1440 (24:00).", "INVALID_BLOCKED": "Room blocked must be a boolean value."};
msg.result.message = messages[msg.result.reasonCode];
msg.payload = msg.result;
return msg;

const cases = [{"id": "T1", "label": "Valid free interval", "input": {"start": 700, "duration": 60, "blocked": false}, "expected": {"availability": true, "valid": true, "reasonCode": "AVAILABLE"}}, {"id": "T2", "label": "Overlap existing booking", "input": {"start": 630, "duration": 60, "blocked": false}, "expected": {"availability": false, "valid": true, "reasonCode": "OVERLAP"}}, {"id": "T3", "label": "Blocked room", "input": {"start": 700, "duration": 60, "blocked": true}, "expected": {"availability": false, "valid": true, "reasonCode": "ROOM_BLOCKED"}}, {"id": "T4", "label": "Zero duration", "input": {"start": 700, "duration": 0, "blocked": false}, "expected": {"availability": false, "valid": false, "reasonCode": "INVALID_DURATION"}}, {"id": "T5", "label": "Duration121", "input": {"start": 700, "duration": 121, "blocked": false}, "expected": {"availability": false, "valid": false, "reasonCode": "INVALID_DURATION"}}, {"id": "T6", "label": "Past start", "input": {"start": 500, "duration": 60, "blocked": false}, "expected": {"availability": false, "valid": false, "reasonCode": "PAST_START"}}, {"id": "T7", "label": "Adjacent interval", "input": {"start": 660, "duration": 60, "blocked": false}, "expected": {"availability": true, "valid": true, "reasonCode": "AVAILABLE"}}];
const suiteId = String(Date.now()) + Math.random().toString(16).slice(2);
flow.set("suite:" + suiteId, { before: JSON.stringify(flow.get("bookings")), rows: [] });
const messages = cases.map(c => ({ ...msg, payload: c.input, suiteId, caseId: c.id, caseLabel: c.label, expected: c.expected }));
return [messages];

const state = flow.get("suite:" + msg.suiteId);
if (!state) return null;
const actual = msg.payload;
const expected = msg.expected;
const pass = actual.availability === expected.availability && actual.valid === expected.valid && actual.reasonCode === expected.reasonCode;
state.rows.push({ case: msg.caseId, test: msg.caseLabel, expected: expected.reasonCode, observed: actual.reasonCode, result: pass ? "PASS" : "FAIL" });
if (state.rows.length < 7) { flow.set("suite:" + msg.suiteId, state); return null; }
state.rows.sort((a,b) => a.case.localeCompare(b.case));
const unchanged = state.before === JSON.stringify(flow.get("bookings"));
state.rows.push({ case: "T8", test: "Booking data unchanged", expected: "UNCHANGED", observed: unchanged ? "UNCHANGED" : "CHANGED", result: unchanged ? "PASS" : "FAIL" });
flow.set("suite:" + msg.suiteId, undefined);
msg.payload = state.rows;
return msg;
